import base64, gzip, os, subprocess, sys
FILES = {'app/bot/handlers.py': '', 'app/bot/keyboards.py': '', 'app/bot/bot.py': '', 'app/core/database.py': '', 'app/services/telegram_notify.py': '', 'app/web/routes/api.py': '', 'app/services/xui_client.py': '', 'app/services/vpn_provisioner.py': ''}

APP_DIR = '/opt/vpn_store' if os.path.isdir('/opt/vpn_store') else os.getcwd()
print(f'==> Applying full patch to {APP_DIR}...')

for rel_path, b64_data in FILES.items():
    full_path = os.path.join(APP_DIR, rel_path)
    os.makedirs(os.path.dirname(full_path), exist_ok=True)
    raw = gzip.decompress(base64.b64decode(b64_data))
    with open(full_path, 'wb') as f:
        f.write(raw)
    print(f'  [✓] Updated {rel_path}')

# Clear python cache
os.system(f'find {APP_DIR} -name "*.pyc" -delete 2>/dev/null || true')
os.system(f'find {APP_DIR} -type d -name "__pycache__" -exec rm -rf {{}} + 2>/dev/null || true')

# Stop service and kill ALL lingering/conflicting bot and uvicorn processes
print('==> Stopping lingering processes...')
os.system('systemctl stop vpnstore-bot.service 2>/dev/null || true')
os.system('pkill -9 -f "app.bot.bot" 2>/dev/null || true')
os.system('pkill -9 -f "bot.py" 2>/dev/null || true')
os.system('pkill -9 -f uvicorn 2>/dev/null || true')
os.system('sleep 2')

# Restart systemd services cleanly
print('==> Starting clean systemd services...')
os.system('systemctl daemon-reload')
os.system('systemctl restart vpnstore-web.service')
os.system('systemctl restart vpnstore-bot.service')
print('==> Status of vpnstore-bot:')
os.system('systemctl status vpnstore-bot.service --no-pager -l')
print('')
print('✅ All files updated and bot service started cleanly!')
